import { useState, type ReactNode } from 'react'
import { Slider } from './Plot'
import { Plane, Arrow, Dot, C, fmt, vec, type PS } from './widgets7'

/** light lattice generated by two vectors (lines c1 = n and c2 = n) */
function Lattice({ s, b1, b2, R, color = C.purple }: { s: PS; b1: number[]; b2: number[]; R: number; color?: string }) {
  const out: ReactNode[] = []
  for (let n = -R; n <= R; n++) {
    out.push(<line key={'a' + n} x1={s.sx(n * b1[0] - R * b2[0])} y1={s.sy(n * b1[1] - R * b2[1])} x2={s.sx(n * b1[0] + R * b2[0])} y2={s.sy(n * b1[1] + R * b2[1])} stroke={color} strokeOpacity={0.55} strokeWidth={1.4} />)
    out.push(<line key={'b' + n} x1={s.sx(n * b2[0] - R * b1[0])} y1={s.sy(n * b2[1] - R * b1[1])} x2={s.sx(n * b2[0] + R * b1[0])} y2={s.sy(n * b2[1] + R * b1[1])} stroke={color} strokeOpacity={0.55} strokeWidth={1.4} />)
  }
  return <g>{out}</g>
}
const det2 = (a: number[], b: number[]) => a[0] * b[1] - a[1] * b[0]
const solve2 = (b1: number[], b2: number[], v: number[]) => {
  const d = det2(b1, b2)
  return [det2(v, b2) / d, det2(b1, v) / d]
}

/* ── 7a. Span painter: reach the star with two arrows ── */
const A_VEC = [2, 1]
const B_OPTS = [{ b: [-1, 2], name: 'b = (−1, 2)' }, { b: [0, 1], name: 'b = (0, 1)' }, { b: [4, 2], name: 'b = (4, 2) 😮 a ට සමාන්තරයි' }]
const STAR = [3, 4]
export function SpanPainter() {
  const [bi, setBi] = useState(0)
  const [s, setS] = useState(1), [t, setT] = useState(1)
  const [all, setAll] = useState(false)
  const b = B_OPTS[bi].b
  const P = [s * A_VEC[0] + t * b[0], s * A_VEC[1] + t * b[1]]
  const par = det2(A_VEC, b) === 0
  const reached = Math.hypot(P[0] - STAR[0], P[1] - STAR[1]) < 0.01
  const dots: number[][] = []
  if (all) for (let i = -4; i <= 4; i++) for (let j = -4; j <= 4; j++) dots.push([i * A_VEC[0] + j * b[0], i * A_VEC[1] + j * b[1]])
  return (
    <div className="viz">
      <p>🤖 රොබෝට යන්න පුළුවන් <b>a = (2, 1)</b> සහ <b>b = {vec(b)}</b> යන ඊතල 2 ඔස්සේ පමණයි. ⭐ (3, 4) ට යන්න s සහ t සොයන්න!</p>
      <div className="row">{B_OPTS.map((o, k) => <button key={k} className={`chip ${k === bi ? 'good' : ''}`} onClick={() => setBi(k)}>{o.name}</button>)}</div>
      <Plane R={6} maxWidth={480}>
        {(sc) => (
          <>
            {dots.map((d, k) => <circle key={k} cx={sc.sx(d[0])} cy={sc.sy(d[1])} r={3.5} fill={C.purple} fillOpacity={0.6} />)}
            <Arrow s={sc} to={[s * A_VEC[0], s * A_VEC[1]]} color={C.blue} w={3} label="s·a" />
            <Arrow s={sc} from={[s * A_VEC[0], s * A_VEC[1]]} to={P} color={C.orange} w={3} label="t·b" />
            <Arrow s={sc} to={P} color={C.green} w={4} dash />
            <text x={sc.sx(STAR[0])} y={sc.sy(STAR[1]) + 8} textAnchor="middle" fontSize={26}>⭐</text>
            <Dot s={sc} p={P} color={reached ? C.green : C.red} r={7} />
          </>
        )}
      </Plane>
      <div className="row"><div style={{ flex: 1, minWidth: 180 }}><Slider label="s (a කීපාරක්)" v={s} set={setS} min={-4} max={4} step={0.5} /></div><div style={{ flex: 1, minWidth: 180 }}><Slider label="t (b කීපාරක්)" v={t} set={setT} min={-4} max={4} step={0.5} /></div></div>
      <label style={{ display: 'block', margin: '6px 0' }}><input type="checkbox" checked={all} onChange={(e) => setAll(e.target.checked)} /> 🎨 මේ ඊතල 2 න් යන්න පුළුවන් සියලු තැන් පාට කරන්න (span)</label>
      <div className="say">
        P = {fmt(s)}·(2, 1) + {fmt(t)}·{vec(b)} = <b>{vec(P)}</b> {reached && '🎯 ⭐ ට ආවා! (s = ' + fmt(s) + ', t = ' + fmt(t) + ')'}
        <br />{par ? '😮 a සහ b එකම රේඛාවේ (සමාන්තර) — ඔයාට යන්න පුළුවන් එක රේඛාවක් පමණයි! span = රේඛාවක්. ⭐ ට යන්න බෑ.' : '😀 ඊතල දෙක වෙනස් දිශා වල — පාට කළොත් මුළු තලයම පාට වෙනවා. span = ℝ² (මුළු තලය).'}
      </div>
    </div>
  )
}

/* ── 7b. RGB mixer: colours are linear combinations ── */
export function RgbMixer() {
  const [r, setR] = useState(255), [g, setG] = useState(140), [b, setB] = useState(0)
  const lum = 0.299 * r + 0.587 * g + 0.114 * b
  return (
    <div className="viz">
      <div style={{ background: `rgb(${r},${g},${b})`, color: lum > 140 ? '#111827' : '#ffffff', borderRadius: 18, padding: 20, textAlign: 'center', fontWeight: 800, fontSize: '1.2em', border: '3px solid #94a3b8' }}>
        {r}·(රතු) + {g}·(කොළ) + {b}·(නිල්) = ({r}, {g}, {b})
      </div>
      <Slider label="🔴 රතු" v={r} set={setR} min={0} max={255} step={5} />
      <Slider label="🟢 කොළ" v={g} set={setG} min={0} max={255} step={5} />
      <Slider label="🔵 නිල්" v={b} set={setB} min={0} max={255} step={5} />
      <div className="say">ෆෝන් තිරයේ ඕනෑම පාටක් = (රතු, කොළ, නිල්) <b>රේඛීය සංයෝජනයක්</b> (linear combination). මූලික පාට 3 න් හැම පාටක්ම හැදෙනවා ⟹ ඒ 3 ට කියන්නේ <b>පාදකය (basis)</b>; පාට අවකාශයේ <b>මානය 3</b>.</div>
    </div>
  )
}

/* ── 8. Parallelogram area = |determinant| ── */
export function ParallelogramDet() {
  const [x, setX] = useState(1), [y, setY] = useState(2)
  const v1 = [2, 1], v2 = [x, y], sum = [2 + x, 1 + y]
  const d = det2(v1, v2)
  const ok = Math.abs(d) > 1e-9
  const pts = (sc: PS) => [[0, 0], v1, sum, v2].map((p) => `${sc.sx(p[0])},${sc.sy(p[1])}`).join(' ')
  return (
    <div className="viz">
      <Plane R={4} maxWidth={440}>
        {(sc) => (
          <>
            <polygon points={pts(sc)} fill={ok ? C.green : C.red} fillOpacity={0.3} stroke={ok ? C.green : C.red} strokeWidth={2} />
            <Arrow s={sc} to={v1} color={C.blue} label="v₁" />
            <Arrow s={sc} to={v2} color={C.orange} label="v₂" />
            <Dot s={sc} p={[0, 0]} color="#334155" />
          </>
        )}
      </Plane>
      <Slider label="v₂ ගේ x" v={x} set={setX} min={-3} max={3} step={0.5} />
      <Slider label="v₂ ගේ y" v={y} set={setY} min={-3} max={3} step={0.5} />
      <div className="say" style={{ fontWeight: 700 }}>
        det = (2)({fmt(y)}) − (1)({fmt(x)}) = <b>{fmt(d)}</b> ⟹ ඒ පරාලෝගමේ වර්ගඵලය = {fmt(Math.abs(d))}.<br />
        {ok ? '✅ වර්ගඵලය ඇත (0 නොවේ) ⟹ v₁, v₂ රේඛීයව ස්වායත්තයි.' : '❌ පරාලෝගමය සමතලා වුණා (වර්ගඵලය 0) ⟹ v₂, v₁ ට සමාන්තරයි ⟹ රේඛීයව පරායත්තයි!'}
      </div>
    </div>
  )
}

/* ── 9. Basis grid ── */
const BASES = [
  { name: 'සම්මත {(1,0),(0,1)}', b1: [1, 0], b2: [0, 1] },
  { name: '{(1,1),(1,−1)}', b1: [1, 1], b2: [1, -1] },
  { name: '{(2,0),(1,1)}', b1: [2, 0], b2: [1, 1] },
  { name: '{(1,2),(2,4)} 😮', b1: [1, 2], b2: [2, 4] },
]
export function BasisGrid() {
  const [bi, setBi] = useState(1)
  const [c1, setC1] = useState(2), [c2, setC2] = useState(1)
  const { b1, b2 } = BASES[bi]
  const P = [c1 * b1[0] + c2 * b2[0], c1 * b1[1] + c2 * b2[1]]
  const ok = det2(b1, b2) !== 0
  return (
    <div className="viz">
      <div className="row">{BASES.map((x, k) => <button key={k} className={`chip ${k === bi ? 'good' : ''}`} onClick={() => setBi(k)}>{x.name}</button>)}</div>
      <Plane R={6} maxWidth={480}>
        {(sc) => (
          <>
            <Lattice s={sc} b1={b1} b2={b2} R={8} color={ok ? C.purple : C.red} />
            <Arrow s={sc} to={b1} color={C.blue} w={4} label="b₁" />
            <Arrow s={sc} to={b2} color={C.orange} w={4} label="b₂" />
            <Arrow s={sc} to={P} color={C.green} w={3} dash />
            <Dot s={sc} p={P} color={C.green} r={7} label="v" />
          </>
        )}
      </Plane>
      <div className="row"><div style={{ flex: 1, minWidth: 180 }}><Slider label="c₁ (b₁ කීපාරක්)" v={c1} set={setC1} min={-3} max={3} step={1} /></div><div style={{ flex: 1, minWidth: 180 }}><Slider label="c₂ (b₂ කීපාරක්)" v={c2} set={setC2} min={-3} max={3} step={1} /></div></div>
      <div className="say">
        v = {c1}·{vec(b1)} + {c2}·{vec(b2)} = <b>{vec(P)}</b><br />
        {ok ? '✅ පාදකයක්! මේ දෙකෙන් හැදෙන ජාලය (grid) මුළු තලයම වසනවා, හැම ලක්ෂ්‍යයකටම අනන්‍ය (unique) ඛණ්ඩාංක දෙකක් ඇත.' : '❌ පාදකයක් නෙමෙයි: b₂ = 2·b₁ — ජාලය එක රේඛාවකට කඩා වැටුණා. තලයේ බොහෝ තැන් වලට යන්න බෑ.'}
      </div>
    </div>
  )
}

/* ── 10a. Dimension ladder ── */
export function DimensionLadder() {
  const [k, setK] = useState(2)
  const W = 520, H = 220
  const info = [
    { e: '🗿', title: 'ලක්ෂ්‍යය · මානය 0', say: 'ඊතල 0ක් — එක තැනම ⟹ {0} (ශූන්‍ය අවකාශය). කිසිම දිශාවකට යන්න බෑ.' },
    { e: '🚂', title: 'රේඛාවක් · මානය 1', say: 'ස්වායත්ත ඊතල 1ක් — රේල් පීල්ලක් වගේ: ඉස්සරහට / පස්සට පමණයි.' },
    { e: '🐜', title: 'තලයක් · මානය 2', say: 'ස්වායත්ත ඊතල 2ක් — පොළව මත: ඉස්සරහට/පස්සට සහ වමට/දකුණට.' },
    { e: '🐦', title: 'ඉඩ (3D) · මානය 3', say: 'ස්වායත්ත ඊතල 3ක් — අහසේ: ඉහළට/පහළටත් යන්න පුළුවන්. ℝ³.' },
  ][k]
  return (
    <div className="viz">
      <svg className="plot" viewBox={`0 0 ${W} ${H}`} style={{ maxWidth: 520 }}>
        {k === 0 && <circle cx={260} cy={110} r={10} fill={C.red} />}
        {k === 1 && <><line x1={60} y1={150} x2={460} y2={70} stroke={C.blue} strokeWidth={6} strokeLinecap="round" /><text x={250} y={96} fontSize={38}>🚂</text></>}
        {k === 2 && <><polygon points="90,170 360,170 450,60 180,60" fill={C.green} fillOpacity={0.35} stroke={C.green} strokeWidth={3} /><text x={250} y={125} fontSize={36}>🐜</text></>}
        {k === 3 && <>
          <polygon points="150,170 330,170 330,50 150,50" fill={C.purple} fillOpacity={0.15} stroke={C.purple} strokeWidth={3} />
          <polygon points="220,130 400,130 400,10 220,10" fill={C.purple} fillOpacity={0.15} stroke={C.purple} strokeWidth={3} />
          {[[150, 170, 220, 130], [330, 170, 400, 130], [330, 50, 400, 10], [150, 50, 220, 10]].map((l, i) => <line key={i} x1={l[0]} y1={l[1]} x2={l[2]} y2={l[3]} stroke={C.purple} strokeWidth={3} />)}
          <text x={255} y={90} fontSize={34}>🐦</text></>}
      </svg>
      <div style={{ fontSize: '2.2em', textAlign: 'center' }}>{info.e}</div>
      <Slider label="ස්වායත්ත ඊතල ගණන" v={k} set={setK} min={0} max={3} step={1} />
      <div className="say"><b>{info.title}</b> — {info.say}<br />මානය (dimension) = <b>ස්වායත්ත දිශා ගණන</b> = පාදකයේ ඊතල ගණන = <b>{k}</b>.</div>
    </div>
  )
}

/* ── 10b. Kick out the extra vector ── */
const KO = [{ n: 'a', v: [1, 0], col: C.blue }, { n: 'b', v: [0, 1], col: C.orange }, { n: 'c', v: [1, 1], col: C.purple }]
export function KickOutExtra() {
  const [on, setOn] = useState([true, true, true])
  const sel = KO.filter((_, i) => on[i])
  let rank = 0
  if (sel.length > 0) rank = 1
  for (let i = 0; i < sel.length; i++) for (let j = i + 1; j < sel.length; j++) if (det2(sel[i].v, sel[j].v) !== 0) rank = 2
  return (
    <div className="viz">
      <div className="row">{KO.map((x, i) => (
        <button key={x.n} className={`chip ${on[i] ? 'good' : ''}`} onClick={() => setOn(on.map((o, j) => (j === i ? !o : o)))}>{on[i] ? '✂️ ඉවත් කරන්න' : '↩️ ආපහු දාන්න'}: {x.n} = {vec(x.v)}</button>
      ))}</div>
      <Plane R={3} maxWidth={380}>
        {(sc) => (
          <>
            {rank === 2 && <rect x={0} y={0} width={sc.W} height={sc.H} fill={C.green} fillOpacity={0.15} />}
            {rank === 1 && sel[0] && <line x1={sc.sx(-4 * sel[0].v[0])} y1={sc.sy(-4 * sel[0].v[1])} x2={sc.sx(4 * sel[0].v[0])} y2={sc.sy(4 * sel[0].v[1])} stroke={C.green} strokeWidth={8} strokeOpacity={0.35} />}
            {KO.map((x, i) => on[i] && <Arrow key={x.n} s={sc} to={x.v} color={x.col} w={4} label={x.n} />)}
            <Dot s={sc} p={[0, 0]} color="#334155" />
          </>
        )}
      </Plane>
      <div className="say">
        span = {rank === 0 ? 'ලක්ෂ්‍යයක් (0)' : rank === 1 ? 'රේඛාවක්' : 'මුළු තලය ℝ²'} ⟹ <b>මානය = {rank}</b>.
        <br />{on[0] && on[1] && on[2] ? '👀 c = a + b — c අනවශ්‍යයි (a, b තියෙද්දී c අලුත් දිශාවක් දෙන්නේ නෑ). එකක් ඉවත් කරලා බලන්න: මානය තවමත් 2 ද?' : rank === 2 ? '✅ ඊතල 2ක් ඉතිරියි, තවමත් මුළු තලයම — මානය 2.' : rank === 1 ? '⚠️ දැන් එක දිශාවක් විතරයි — රේඛාවක්.' : '⚫ ඊතල නෑ — ලක්ෂ්‍යයක් විතරයි.'}
      </div>
    </div>
  )
}

/* ── 11. Two grids, one point ── */
const COORD_BASES = [
  { name: 'B = {(1,1),(1,−1)}', b1: [1, 1], b2: [1, -1] },
  { name: 'B = {(1,0),(1,1)}', b1: [1, 0], b2: [1, 1] },
  { name: 'B = {(2,0),(0,3)}', b1: [2, 0], b2: [0, 3] },
]
export function TwoGridCoords() {
  const [bi, setBi] = useState(0)
  const [x, setX] = useState(5), [y, setY] = useState(1)
  const { b1, b2 } = COORD_BASES[bi]
  const v = [x, y]
  const c = solve2(b1, b2, v)
  const a1 = [c[0] * b1[0], c[0] * b1[1]]
  return (
    <div className="viz">
      <div className="row">{COORD_BASES.map((q, k) => <button key={k} className={`chip ${k === bi ? 'good' : ''}`} onClick={() => setBi(k)}>{q.name}</button>)}</div>
      <Plane R={7} maxWidth={500}>
        {(sc) => (
          <>
            <Lattice s={sc} b1={b1} b2={b2} R={9} />
            <Arrow s={sc} to={b1} color={C.blue} w={3} label="b₁" />
            <Arrow s={sc} to={b2} color={C.orange} w={3} label="b₂" />
            <Arrow s={sc} to={a1} color={C.blue} w={3} dash />
            <Arrow s={sc} from={a1} to={v} color={C.orange} w={3} dash />
            <Dot s={sc} p={v} color={C.green} r={8} label="v" />
          </>
        )}
      </Plane>
      <div className="row"><div style={{ flex: 1, minWidth: 180 }}><Slider label="v ගේ x (සම්මත)" v={x} set={setX} min={-6} max={6} step={1} /></div><div style={{ flex: 1, minWidth: 180 }}><Slider label="v ගේ y (සම්මත)" v={y} set={setY} min={-6} max={6} step={1} /></div></div>
      <table className="t" style={{ marginTop: 6 }}><tbody>
        <tr><td>🗺️ සම්මත සිතියම (E)</td><td><b>[v]_E = {vec(v)}</b></td></tr>
        <tr><td>🗺️ B සිතියම</td><td><b>[v]_B = {vec(c)}</b></td></tr>
      </tbody></table>
      <div className="say">
        පරීක්ෂාව: {fmt(c[0])}·{vec(b1)} + {fmt(c[1])}·{vec(b2)} = <b>{vec([c[0] * b1[0] + c[1] * b2[0], c[0] * b1[1] + c[1] * b2[1]])}</b> ✔ <br />
        ලක්ෂ්‍යය (v) එකම තැනයි — වෙනස් වුණේ <b>ලිපිනය (ඛණ්ඩාංක)</b> පමණයි!
      </div>
    </div>
  )
}

/* ── 12a. Row reduction stepper ── */
interface RStep { m: number[][]; rows?: number[]; cols?: number[]; cells?: [number, number][]; note: ReactNode }
const A0 = [[1, 2, 3], [2, 4, 6], [1, 1, 1]]
const E1 = [[1, 2, 3], [0, 0, 0], [1, 1, 1]]
const E2 = [[1, 2, 3], [0, 0, 0], [0, -1, -2]]
const E3 = [[1, 2, 3], [0, -1, -2], [0, 0, 0]]
const RSTEPS: RStep[] = [
  { m: A0, note: <>මේ අපේ න්‍යාසය <b>A</b> (පේළි 3, තීරු n = 3). දැන් <b>පේළි-ඌනනය (row reduction)</b> කරමු 🪜</> },
  { m: E1, rows: [1], note: <>R₂ ← R₂ − 2R₁ : දෙවන පේළිය = පළමු පේළියේ දෙගුණයක් නිසා <b>ශූන්‍ය</b> වුණා (අනවශ්‍ය පේළියක් 🗑️)</> },
  { m: E2, rows: [2], note: <>R₃ ← R₃ − R₁ : (1,1,1) − (1,2,3) = (0, −1, −2)</> },
  { m: E3, rows: [1, 2], note: <>R₂ ↔ R₃ : ශූන්‍ය පේළිය පහළට. දැන් <b>පියගැට (echelon) හැඩය</b> ලැබුණා ✅</> },
  { m: E3, cells: [[0, 0], [1, 1]], cols: [0, 1], note: <>ප්‍රධාන ලක්ෂ්‍ය (pivots) 2ක්: තීරු 1 සහ 2. ⟹ <b>rank(A) = 2</b></> },
  { m: A0, cols: [0, 1], note: <>🏛️ <b>තීරු අවකාශය Col(A)</b> හි පාදකය: <u>මුල් A</u> හි pivot තීරු — <b>(1,2,1) සහ (2,4,1)</b>. (පේළි-ඌනනය කළ න්‍යාසයෙන් නෙමෙයි!) dim = 2</> },
  { m: E3, rows: [0, 1], note: <>🛤️ <b>පේළි අවකාශය Row(A)</b> හි පාදකය: echelon න්‍යාසයේ <b>ශූන්‍ය නොවන</b> පේළි — <b>(1,2,3) සහ (0,−1,−2)</b>. dim = 2</> },
  { m: E3, cols: [2], note: <>🕳️ <b>ශූන්‍ය අවකාශය Null(A)</b>: x₃ = t (නිදහස් විචල්‍යය). −x₂ − 2t = 0 ⟹ x₂ = −2t; x₁ + 2(−2t) + 3t = 0 ⟹ x₁ = t. ⟹ x = t·(1, −2, 1). පාදකය <b>(1, −2, 1)</b>; nullity = 1. පරීක්ෂාව: A·(1,−2,1) = (1−4+3, 2−8+6, 1−2+1) = (0,0,0) ✔</> },
  { m: E3, note: <>⚖️ <b>rank + nullity = n</b> ⟹ 2 + 1 = 3 (තීරු ගණන) ✅</> },
]
export function RowReduceStepper() {
  const [k, setK] = useState(0)
  const st = RSTEPS[k]
  const hl = (r: number, c: number) => (st.cells?.some(([a, b]) => a === r && b === c) ? 'pivot' : st.rows?.includes(r) || st.cols?.includes(c) ? 'on' : '')
  return (
    <div className="viz">
      <div style={{ overflowX: 'auto' }}>
        <table style={{ margin: '0 auto', borderCollapse: 'separate', borderSpacing: 4 }}>
          <tbody>
            {st.m.map((row, r) => (
              <tr key={r}>
                {row.map((x, c) => {
                  const h = hl(r, c)
                  return <td key={c} style={{ width: 54, height: 44, textAlign: 'center', fontWeight: 800, fontSize: '1.2em', borderRadius: 10, border: '2px solid #94a3b8', background: h === 'pivot' ? '#fb923c' : h === 'on' ? '#fde68a' : '#e0e7ff', color: '#1e1b4b' }}>{fmt(x)}</td>
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="say" style={{ minHeight: 70 }}>{st.note}</div>
      <div className="row">
        <button className="btn" disabled={k >= RSTEPS.length - 1} onClick={() => setK(k + 1)}>👉 ඊළඟ ({k + 1}/{RSTEPS.length})</button>
        <button className="btn alt" disabled={k === 0} onClick={() => setK(k - 1)}>👈 ආපසු</button>
        <button className="btn alt" disabled={k === 0} onClick={() => setK(0)}>🔁 මුල සිට</button>
      </div>
    </div>
  )
}

/* ── 12b. Rank + nullity = n ── */
export function RankNullityMeter() {
  const [m, setM] = useState(3), [n, setN] = useState(5), [rk, setRk] = useState(2)
  const r = Math.min(rk, m, n)
  return (
    <div className="viz">
      <div style={{ display: 'flex', gap: 4, margin: '8px 0', flexWrap: 'wrap' }}>
        {Array.from({ length: n }, (_, i) => (
          <div key={i} style={{ flex: '1 0 40px', textAlign: 'center', padding: '10px 4px', borderRadius: 10, fontWeight: 800, background: i < r ? '#93c5fd' : '#fdba74', color: '#1e1b4b', border: '2px solid #64748b' }}>
            {i < r ? '📌' : '🆓'}<div style={{ fontSize: '.7em' }}>{i < r ? 'pivot' : 'free'}</div>
          </div>
        ))}
      </div>
      <div className="row">
        <div style={{ flex: 1, minWidth: 160 }}><Slider label="පේළි ගණන m" v={m} set={setM} min={1} max={8} step={1} /></div>
        <div style={{ flex: 1, minWidth: 160 }}><Slider label="තීරු ගණන n" v={n} set={setN} min={1} max={8} step={1} /></div>
        <div style={{ flex: 1, minWidth: 160 }}><Slider label="rank" v={r} set={setRk} min={0} max={Math.min(m, n)} step={1} /></div>
      </div>
      <div className="say" style={{ fontWeight: 700 }}>
        rank ({r}) + nullity ({n - r}) = n ({n}) ✅<br />
        Col(A) ⊆ ℝ<sup>{m}</sup>, මානය {r} · Row(A) ⊆ ℝ<sup>{n}</sup>, මානය {r} · Null(A) ⊆ ℝ<sup>{n}</sup>, මානය {n - r}
      </div>
    </div>
  )
}
